import{_ as e,o,c as a,aj as n}from"./chunks/framework.BwH0p-pt.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/introduction/index.md","filePath":"2.1/introduction/index.md","lastUpdated":1781079046000}'),r={name:"2.1/introduction/index.md"};function i(s,t,d,c,p,l){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> is an open-source Product Information Management (PIM) system built on the <strong>Laravel 12</strong> framework and requires <strong>PHP 8.3</strong>. It helps businesses organize, manage, and enrich their product information in one central repository.</p><div class="tip custom-block"><p class="custom-block-title">Current Version — v2.1.0</p><p>This guide covers UnoPim <strong>v2.1.0</strong>, released 13 May 2026. v2.1.0 brings a production-ready Docker stack, one-click Demo Data seeding, the <code>ManageAssociations</code> AI Agent tool, MagicAI Custom Providers, async product webhooks, clickable dashboard stats, and a dedicated security hardening pass. See <strong><a href="./../releases/">What&#39;s New</a></strong> for the full list.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p><strong>1) Centralized Product Management-</strong> Manage all your product data in one place with support for Simple and Configurable product types.</p><p><strong>2) Data Enrichment-</strong> Enhance your product information with detailed attributes, including support for 12 data types and swatch types for visual attribute options.</p><p><strong>3) Category Management-</strong> Organize products into categories for easier navigation, with customizable category fields.</p><p><strong>4) User Management-</strong> Control user access and permissions with role-based access control.</p><p><strong>5) API Integration-</strong> Seamlessly integrate with other systems via RESTful APIs with OAuth 2.0 authentication.</p><p><strong>6) Localization-</strong> Support for multiple languages and locales with automatic AI-powered translation.</p><p><strong>7) Import/Export Functionality-</strong> Easily import and export product data using CSV, XLS, and XLSX formats, with drag-and-drop file upload, real-time job tracking, and pause/resume/cancel controls.</p><p><strong>8) Magic AI for Product Content Generation-</strong> Automatically generate engaging product content using advanced LLM technology with support for 10+ AI providers including OpenAI, Gemini, Anthropic, Ollama, and Groq.</p><p><strong>9) Multi-Channel Support-</strong> Manage and distribute your product data across multiple sales channels from a single platform.</p><p><strong>10) AI Agent Chat-</strong> Interact with your PIM using natural language through the AI Agent Chat interface with 30+ built-in PIM tools for product management, data quality, and bulk operations.</p><p><strong>11) Product Completeness-</strong> Monitor data quality with product completeness scoring that tracks how much required information has been filled in per channel and locale.</p><p><strong>12) Notifications-</strong> Stay informed with in-app and email notifications for import/export jobs, product changes, and system events.</p><p><strong>13) Webhooks-</strong> Automate workflows with product update webhooks that trigger HTTP callbacks when product data changes.</p><p><strong>14) Enhanced Dashboard-</strong> Get a comprehensive overview of your catalog with widgets for product statistics, activity charts, completeness scores, channel readiness, and recent operations.</p><p><strong>15) Product Bulk Edit-</strong> Edit multiple products at once by selecting them from the datagrid and applying bulk changes to shared attributes.</p><p><strong>16) PostgreSQL Support-</strong> Full support for PostgreSQL databases in addition to MySQL for improved cross-database compatibility.</p><p><strong>17) Production-Ready Docker Setup</strong> - Spin up the full stack with one command using the official Docker Hub images. Multi-container setup with Nginx + PHP-FPM (Apache fallback available), Redis, Elasticsearch, and Mailpit — all with healthchecks, OPcache-tuned <code>php.ini</code>, and an auto-publish workflow.</p><p><strong>18) Demo Data Seeding</strong> - Evaluate UnoPim immediately with realistic sample data. Toggle demo data from the installer wizard, pass <code>--with-demo-data</code> to <code>php artisan unopim:install</code>, or run the standalone <code>php artisan unopim:install:demo-data</code> command at any time after install.</p><p><strong>19) MagicAI Custom Providers</strong> - Plug in any OpenAI-compatible service — self-hosted gateways, proxies, or alternative endpoints — by selecting the <em>Custom</em> provider on the Magic AI Platforms page and supplying your own base URL.</p><p><strong>20) Async Product Webhooks</strong> - Product create/update webhooks are dispatched in the background as a queued <code>SendProductWebhook</code> job, so admin actions return immediately even when the receiving endpoint is slow.</p><p><strong>21) Clickable Dashboard Stats</strong> - Product-stats tiles on the Dashboard (Active, Inactive, Enriched, With Variants, …) now act as filter chips — click one to deep-link into the product grid pre-filtered to that set.</p><p><strong>22) Security Hardening</strong> - Admin login rate limiting, server-side password validation, forgot-password user-enumeration protection, open-redirect blocking, user-edit privilege-escalation guard, <code>clean_content()</code> XSS sanitization helper, and <code>APP_DEBUG_ALLOWED_IPS</code> IP-restricted debugbar.</p>',26)])])}const h=e(r,[["render",i]]);export{g as __pageData,h as default};
